describe('Unsaved Form Navigation Warning', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should display warning when user attempts to navigate away from unsaved form', () => {
    // Intercept the navigation route
    cy.intercept('GET', '/form-page').as('getFormPage');
    cy.get('[data-testid="form-container"]').should('be.visible');

    // Fill form with data
    cy.get('[data-testid="input-name"]').type('John Doe');
    cy.get('[data-testid="input-email"]').type('john@example.com');
    cy.get('[data-testid="input-message"]').type('Hello, this is a test message');

    // Verify form is not submitted yet
    cy.get('[data-testid="form-status"]').should('contain', 'Form is unsaved');

    // Attempt to navigate away
    cy.get('[data-testid="navigation-button"]').click();

    // Verify warning is displayed
    cy.get('[data-testid="unsaved-warning"]').should('be.visible');
    cy.get('[data-testid="unsaved-warning"]').should('contain', 'You have unsaved changes');

    // Verify navigation route was intercepted
    cy.wait('@getFormPage').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify form is still visible
    cy.get('[data-testid="form-container"]').should('be.visible');
  });

  it('should clear warning when form is successfully submitted', () => {
    // Fill form with data
    cy.get('[data-testid="input-name"]').type('Jane Smith');
    cy.get('[data-testid="input-email"]').type('jane@example.com');
    cy.get('[data-testid="input-message"]').type('Please review my changes');

    // Verify form is not submitted yet
    cy.get('[data-testid="form-status"]').should('contain', 'Form is unsaved');

    // Submit form
    cy.get('[data-testid="submit-button"]').click();

    // Verify warning is cleared
    cy.get('[data-testid="unsaved-warning"]').should('not.exist');

    // Verify form is submitted
    cy.get('[data-testid="form-status"]').should('contain', 'Form submitted successfully');

    // Verify navigation route was not intercepted
    cy.intercept('GET', '/form-page').as('getFormPage');
    cy.wait('@getFormPage').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify form is still visible
    cy.get('[data-testid="form-container"]').should('be.visible');
  });
});
